interface Counts { [word: string]: number; }

function countWords(text: string): Counts {
  const counts: Counts = {};
  for (const w of text.split(' ')) {
    counts[w] = (counts[w] ?? 0) + 1;
  }
  return counts;
}

console.log(countWords('a b a c a b'));

