solution.code:
interface Prices { [item: string]: number; }
const prices: Prices = { apple: 2, pear: 3 };

function format(item: string): string {
  const price = prices[item];
  if (price === undefined) return 'N/A';
  return '$' + price.toFixed(2);
}

console.log(format('apple'));
console.log(format('banana')); // 'N/A'

function groupBy<T>(items: T[], keyOf: (item: T) => string): Record<string, T[]> {
  const out: Record<string, T[]> = {};
  for (const item of items) {
    const k = keyOf(item);
    (out[k] ??= []).push(item);
  }
  return out;
}

const people = [{ city: 'NYC', n: 'A' }, { city: 'LA', n: 'B' }, { city: 'NYC', n: 'C' }];
console.log(groupBy(people, p => p.city));

