function groupBy<T>(items: T[], keyOf: (i: T) => string): Map<string, T[]> {
  const m = new Map<string, T[]>();
  for (const i of items) { const k = keyOf(i); (m.get(k) ?? m.set(k, []).get(k)!).push(i); }
  return m;
}
